/**
 * Auth Axios Instance for Token Management
 *
 * This is a separate axios instance used exclusively for authentication operations:
 * - Token refresh requests
 * - OAuth2 token exchange
 * - Other auth service API calls
 *
 * CRITICAL: Auth requests must go to the AUTH_URL, not DOC2API_URL.
 * Using the wrong domain will cause authentication to fail silently or fail-over to production.
 *
 * Responsibilities:
 * 1. Manage authentication requests to the correct AUTH_URL
 * 2. Handle token refresh without circular dependency with SDK requests
 * 3. Handle 401 errors with automatic token refresh and retry
 * 4. NOT used for regular SDK API calls (use custom-axios-instance.ts for those)
 *
 * Usage:
 * - DO use this for: token refresh, OAuth2 exchanges, auth status checks
 * - DON'T use this for: Document API calls, Preferences API, or any SDK calls
 *
 * Example Usage (in auth store):
 *   import { authAxiosInstance } from 'src/sdk/mutator/auth-axios-instance';
 *
 *   async refreshToken() {
 *     const response = await authAxiosInstance.post('/oauth2/token', {
 *       grant_type: 'refresh_token',
 *       refresh_token: this.refreshToken,
 *     });
 *     return response.data;
 *   }
 */

import axios, {
  AxiosRequestConfig,
  AxiosError,
  AxiosResponse,
  InternalAxiosRequestConfig,
} from 'axios';
import { AUTH_URL } from 'src/pages/APIs';
import {
  getAuthToken,
  refreshAccessToken,
  handleTokenRefreshFailure,
} from 'src/sdk/mutator/auth-token-helpers';

// Extended request config with custom properties for retry logic and timing
interface ExtendedAxiosRequestConfig extends InternalAxiosRequestConfig {
  __requestStartTime?: number;
  __isRetry?: boolean;
}

// ============================================================================
// Token Refresh Queue Management (same pattern as custom-axios-instance.ts)
// ============================================================================

/**
 * Track pending requests to prevent duplicate token refresh calls.
 * When a 401 occurs, if refresh is already in progress, queue the request.
 */
let isRefreshing = false;
let failedQueue: Array<{
  resolve: (value: string | null) => void;
  reject: (reason: unknown) => void;
}> = [];

function processQueue(error: unknown, token: string | null = null): void {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  isRefreshing = false;
  failedQueue = [];
}

// ============================================================================
// Auth Axios Instance Setup
// ============================================================================

/**
 * Create axios instance for authentication operations.
 * CRITICAL: Uses AUTH_URL, not DOC2API_URL
 *
 * This instance:
 * - Communicates with authentication service
 * - Handles token refresh independently
 * - Includes 401 retry logic with token refresh
 * - Includes CORS headers for cross-origin requests
 */
export const AUTH_AXIOS_INSTANCE = axios.create({
  baseURL: AUTH_URL,
  timeout: 60000, // 60 second timeout
  headers: {
    'Content-Type': 'application/json',
  },
});

// ============================================================================
// Request Interceptor: Add token for non-token-refresh requests
// ============================================================================

AUTH_AXIOS_INSTANCE.interceptors.request.use(
  async (config: InternalAxiosRequestConfig) => {
    // DON'T add token for token refresh requests (prevents circular dependency)
    const isTokenEndpoint = config.url?.includes('/oauth2/token');

    if (!isTokenEndpoint) {
      try {
        const token = await getAuthToken();
        if (token) {
          config.headers.set('Authorization', `Bearer ${token}`);
        }
      } catch (error) {
        console.warn('Warning: Failed to add auth token:', error);
      }
    }

    // Track request start time for performance monitoring
    (config as ExtendedAxiosRequestConfig).__requestStartTime = Date.now();

    return config;
  },
  (error: unknown) => Promise.reject(error),
);

// ============================================================================
// Response Interceptor: Handle 401 with token refresh and retry
// ============================================================================

AUTH_AXIOS_INSTANCE.interceptors.response.use(
  (response: AxiosResponse) => {
    // Log request duration for performance monitoring
    const startTime = (response.config as ExtendedAxiosRequestConfig)
      .__requestStartTime;
    if (startTime) {
      const duration = Date.now() - startTime;
      if (duration > 5000) {
        // Log slow requests (> 5 seconds)
        console.warn(
          `Slow auth request: ${response.config.url} took ${duration}ms`,
        );
      }
    }

    return response;
  },
  (error: AxiosError) => handleAuthResponseError(error),
);

/**
 * Handle response errors with 401 retry logic
 *
 * - 401: Token expired, attempt refresh and retry (skip for /oauth2/token)
 * - 403: Invalid/revoked token, logout
 * - Other: Pass through to caller
 */
async function handleAuthResponseError(error: AxiosError): Promise<never> {
  const originalRequest = error.config as ExtendedAxiosRequestConfig | undefined;

  // Skip 401 handling for token refresh requests (prevents infinite loop)
  const isTokenEndpoint = originalRequest?.url?.includes('/oauth2/token');

  if (error.response?.status === 401 && originalRequest && !isTokenEndpoint) {
    // Prevent infinite loop - if request was already retried, don't try again
    if (originalRequest.__isRetry) {
      return Promise.reject(error);
    }

    if (!isRefreshing) {
      isRefreshing = true;

      try {
        // Pass the token the request actually failed with so the auth store
        // refreshes for real when that exact token is still the stored one
        // (DRFS-664) instead of bailing on its client-side expire_time.
        const failingToken = String(
          originalRequest.headers?.Authorization ?? '',
        ).replace(/^Bearer\s+/i, '');
        const newToken = await refreshAccessToken(failingToken || undefined);

        if (newToken) {
          processQueue(null, newToken);

          // Retry original request with new token
          originalRequest.headers.set('Authorization', `Bearer ${newToken}`);
          originalRequest.__isRetry = true;
          return AUTH_AXIOS_INSTANCE(originalRequest);
        } else {
          processQueue(error, null);
          return Promise.reject(error);
        }
      } catch (refreshError) {
        processQueue(refreshError, null);

        // If refresh fails, trigger logout
        handleTokenRefreshFailure();
        return Promise.reject(refreshError);
      }
    } else {
      // Token refresh already in progress, queue this request
      return new Promise((resolve, reject) => {
        failedQueue.push({
          resolve: (token: string | null) => {
            if (token && originalRequest) {
              originalRequest.headers.set('Authorization', `Bearer ${token}`);
              originalRequest.__isRetry = true;
              resolve(AUTH_AXIOS_INSTANCE(originalRequest));
            } else {
              reject(error);
            }
          },
          reject: (err: unknown) => reject(err),
        });
      });
    }
  }

  // Handle 403 Forbidden - Token is invalid/revoked
  if (error.response?.status === 403) {
    console.warn('403 Forbidden: Auth token is invalid or revoked');
    handleTokenRefreshFailure();
    return Promise.reject(error);
  }

  // All other errors - log and pass through
  console.warn('Auth service error:', error.response?.status, error.message);
  return Promise.reject(error);
}

// ============================================================================
// Token Management Helpers
// ============================================================================
//
// getAuthToken, refreshAccessToken, and handleTokenRefreshFailure are shared
// with custom-axios-instance.ts and live in src/sdk/mutator/auth-token-helpers.ts
// (imported at the top of this file).

// ============================================================================
// Auth Mutator Function
// ============================================================================

/**
 * Auth Mutator Function
 *
 * This is the function that Orval would call for authentication API endpoints.
 * Currently used directly by auth store for custom authentication logic.
 *
 * @param config - Axios request configuration
 * @returns Promise that resolves to response data
 */
export const authAxiosInstance = <T>(
  config: AxiosRequestConfig,
): Promise<T> => {
  return AUTH_AXIOS_INSTANCE({
    ...config,
  }).then(({ data }) => data) as Promise<T>;
};

/**
 * Export as both default and named export for flexibility
 */
export default authAxiosInstance;

/**
 * Re-export Axios Types
 */
export type { AxiosRequestConfig, AxiosError, AxiosResponse };

/**
 * Development Notes:
 *
 * 1. Separate Instance Why:
 *    - SDK requests (custom-axios-instance) cannot include auth tokens
 *      because they would need tokens to refresh tokens (circular dependency)
 *    - Auth requests must use a completely separate axios instance
 *    - This ensures authentication works independently
 *
 * 2. Environment-Aware:
 *    - AUTH_URL is dynamically set based on environment (dev, stage, prod)
 *    - Same environment-aware logic as SDK baseURL
 *    - Both use src/pages/APIs.ts for URL configuration
 *
 * 3. Token Injection:
 *    - Adds Bearer token for non-token-endpoint requests
 *    - Token endpoints (/oauth2/token) skip token injection to prevent circular dependency
 *    - Uses lazy loading to avoid circular dependencies during app initialization
 *
 * 4. 401 Handling:
 *    - Automatically refreshes token and retries request on 401
 *    - Token endpoints skip 401 retry to prevent infinite loops
 *    - Uses queue to handle concurrent 401 responses
 *    - Same pattern as custom-axios-instance.ts for consistency
 *
 * 5. Error Handling:
 *    - 401: Refresh token and retry (except for token endpoints)
 *    - 403: Logout user immediately
 *    - Other: Log and pass through to caller
 *
 * 6. Cors and Headers:
 *    - Includes 'Content-Type: application/json'
 *    - Allows auth service to handle cross-origin requests
 *    - May need adjustment if auth service requires different headers
 */
